package run.ikaros.finance; import java.time.Instant; import java.util.UUID; import java.math.BigDecimal; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @Service public class ExchangeRateService{private final ExchangeRateRepository rates;private final FinanceLedgerAccessService access;public ExchangeRateService(ExchangeRateRepository r,FinanceLedgerAccessService x){rates=r;access=x;}public Mono<ExchangeRateView> create(UUID a,UUID l,CreateExchangeRateRequest q){if(q.rate().signum()<=0)return Mono.error(new IllegalArgumentException("汇率必须大于 0"));return access.requireEditor(a,l).then(rates.save(new ExchangeRateEntity(null,l,a,q.fromCurrency().toUpperCase(),q.toCurrency().toUpperCase(),q.rate(),q.effectiveAt(),q.provider(),q.source(),Instant.now(),null))).map(this::view);}public Flux<ExchangeRateView> list(UUID a,UUID l){return access.access(a,l).flatMapMany(x->rates.findAllByLedgerIdOrderByEffectiveAtDesc(l).map(this::view));}private ExchangeRateView view(ExchangeRateEntity x){return new ExchangeRateView(x.id(),x.fromCurrency(),x.toCurrency(),x.rate(),x.effectiveAt(),x.provider(),x.source());}}
